const b=$json.body??$json;
const character=String(b.character||'MONA').toUpperCase();
if(!['MONA','NAYA','BOTH','ALL'].includes(character)) throw new Error('CHARACTER_INVALID');
const mode=String(b.mode||'PHOTO').toUpperCase();
if(mode!=='PHOTO') throw new Error('PHOTO_ONLY_IN_REAL_PREVIEW_TEST_V01');
const prompt=String(b.prompt||'').trim() || 'Premium photorealistic Amsterdam lifestyle portrait, natural light, realistic skin, elegant cinematic composition.';
const location=String(b.location||'Amsterdam').trim();
const MONA_URL='https://d2ol7oe51mr4n9.cloudfront.net/user_3IbQt5kDpDnK6Ec0xXtin2Yvkk5/033c8c57-49e5-49aa-a601-7e0a225ebb6d.jpg';
const NAYA_URL='https://d2ol7oe51mr4n9.cloudfront.net/user_3IbQt5kDpDnK6Ec0xXtin2Yvkk5/6632cfdd-10ad-4c61-9c1c-36367332027b.jpg';
let refs=[], identity='';
if(character==='MONA'){refs=[MONA_URL];identity='Mona Moon Ice Lady. Preserve the exact same adult woman identity, face, hair and proportions from the reference. Elegant premium photorealistic styling.';}
else if(character==='NAYA'){refs=[NAYA_URL];identity='Naya Noire. Preserve the exact same adult woman identity, face, hair and proportions from the reference. Dark-glam premium photorealistic styling.';}
else {refs=[MONA_URL,NAYA_URL];identity='Mona Moon and Naya Noire together in one shared scene. Preserve both distinct adult identities exactly; do not blend faces or traits.';}
return [{json:{source:'VAIRA_ANDROID',character,mode:'PHOTO',prompt,location,publish:false,refs,requestBody:{image_urls:refs,prompt:`${identity} LOCATION: ${location}. SCENE: ${prompt}. Natural anatomy and skin. No text or watermark. Platform-safe.`,resolution:'2k',aspect_ratio:'9:16',quality:'high',moderation:'auto',enhance_prompt:false}}}];

const r=$json.body??$json;
const ctx=$('VAIRA • NORMALIZE + CHARACTER REFERENCES').item.json;
if(r.error) throw new Error('HIGGSFIELD_SUBMIT_FAILED:'+JSON.stringify(r.error));
const requestId=r.request_id??r.requestId??r.id;
const statusUrl=r.status_url??r.statusUrl??(requestId?`https://api.higgsfield.ai/requests/${requestId}/status`:null);
if(!requestId||!statusUrl) throw new Error('HIGGSFIELD_REQUEST_ID_MISSING:'+JSON.stringify(r));
return [{json:{...ctx,requestId,statusUrl,pollCount:0}}];

const r=$json.body??$json;
const p=$('HF • WAIT 8s').item.json;
if(r.error) throw new Error('HIGGSFIELD_STATUS_ERROR:'+JSON.stringify(r.error));
const status=String(r.status??r.state??'').toLowerCase();
if(['failed','nsfw','canceled','cancelled'].includes(status)) throw new Error('HIGGSFIELD_TERMINAL_'+status.toUpperCase());
const previewUrl=r.images?.[0]?.url??r.result?.images?.[0]?.url??r.output?.images?.[0]?.url??r.image?.url??r.result?.image?.url??r.video?.url??r.result?.video?.url??r.output?.video?.url??r.videos?.[0]?.url??r.result?.videos?.[0]?.url??null;
const pollCount=Number(p.pollCount||0)+1;
const ready=status==='completed'||Boolean(previewUrl);
if(pollCount>45&&!ready) throw new Error('HIGGSFIELD_POLL_TIMEOUT');
return [{json:{...p,status:status||'pending',previewUrl,pollCount,ready}}];

const x=$json;
if(!x.previewUrl) throw new Error('PREVIEW_URL_MISSING');
return [{json:{accepted:true,status:'completed',character:x.character,mode:x.mode,previewUrl:x.previewUrl,publish:false,approvalRequired:true,requestId:x.requestId}}];
